o=$(BOOKINGS=$t bash src/book.sh aoi 2026-01-05 14:00 15:00 w 5 2>/dev/null); [ -z "$o" ] || { echo "over capacity should print nothing on stdout"; fail=1; }
r=$(mktemp); printf '# room\tcapacity\nsolo\t1\n' > "$r"
BOOKINGS=$t ROOMS=$r bash src/book.sh solo 2026-01-05 09:00 10:00 q >/dev/null 2>&1; [ $? = 0 ] || { echo "omitted people should count as 1 and fit in solo (capacity 1)"; fail=1; }
BOOKINGS=$t ROOMS=$r bash src/book.sh solo 2026-01-05 11:00 12:00 q 2 >/dev/null 2>&1; [ $? = 1 ] || { echo "2 people in solo (capacity 1) should exit 1"; fail=1; }
rm -f "$t" "$r"; exit $fail

